import { i as enquiries, t as db } from "../../../../chunks/db.js";
import { i as superValidate, n as message, t as fail } from "../../../../chunks/client2.js";
import "../../../../chunks/dist2.js";
import { t as zod } from "../../../../chunks/adapters.js";
import { desc, eq } from "drizzle-orm";
import { z } from "zod/v4";
//#region src/routes/dashboard/enquiries/schema.ts
var markSeen = z.object({ id: z.coerce.number() });
var statusSchema = z.object({
	id: z.coerce.number(),
	status: z.enum([
		"new",
		"in_progress",
		"closed"
	])
});
var deleteEnquiry = z.object({ id: z.coerce.number() });
//#endregion
//#region src/routes/dashboard/enquiries/+page.server.ts
var load = async () => {
	const [seenForm, statusForm, deleteForm, rows] = await Promise.all([
		superValidate(zod(markSeen)),
		superValidate(zod(statusSchema)),
		superValidate(zod(deleteEnquiry)),
		db.select().from(enquiries).orderBy(desc(enquiries.createdAt))
	]);
	return {
		seenForm,
		statusForm,
		deleteForm,
		rows
	};
};
var actions = {
	seen: async ({ request }) => {
		const form = await superValidate(request, zod(markSeen));
		if (!form.valid) return fail(400, { form });
		try {
			const [result] = await db.update(enquiries).set({ seen: true }).where(eq(enquiries.id, form.data.id));
			if (result.affectedRows === 0) return message(form, {
				type: "error",
				text: "That enquiry no longer exists"
			}, { status: 404 });
			return message(form, {
				type: "success",
				text: "Marked as seen"
			});
		} catch (err) {
			console.error("Failed to mark enquiry as seen:", err);
			return message(form, {
				type: "error",
				text: "Could not update enquiry"
			}, { status: 500 });
		}
	},
	status: async ({ request }) => {
		const form = await superValidate(request, zod(statusSchema));
		if (!form.valid) return fail(400, { form });
		try {
			const [result] = await db.update(enquiries).set({ status: form.data.status }).where(eq(enquiries.id, form.data.id));
			if (result.affectedRows === 0) return message(form, {
				type: "error",
				text: "That enquiry no longer exists"
			}, { status: 404 });
			return message(form, {
				type: "success",
				text: "Enquiry updated"
			});
		} catch (err) {
			console.error("Failed to update enquiry:", err);
			return message(form, {
				type: "error",
				text: "Could not update enquiry"
			}, { status: 500 });
		}
	},
	delete: async ({ request }) => {
		const form = await superValidate(request, zod(deleteEnquiry));
		if (!form.valid) return fail(400, { form });
		try {
			const [result] = await db.delete(enquiries).where(eq(enquiries.id, form.data.id));
			if (result.affectedRows === 0) return message(form, {
				type: "error",
				text: "That enquiry was already deleted"
			}, { status: 404 });
			return message(form, {
				type: "success",
				text: "Enquiry deleted"
			});
		} catch (err) {
			console.error("Failed to delete enquiry:", err);
			return message(form, {
				type: "error",
				text: "Could not delete enquiry"
			}, { status: 500 });
		}
	}
};
//#endregion
export { actions, load };
